        // ── Scenario builders ────────────────────────────────────────────────────────────────────

        static SkillData Phys(Element elem = Element.Neutral, float power = 1f, int hits = 1,
                              TargetMode tgt = TargetMode.SingleEnemy)
            => new() { Id = "s", Type = SkillType.Physical, DamageType = DamageType.Physical,
                       Element = elem, Target = tgt, PowerMultiplier = power, HitCount = hits,
                       SpCost = 0, PoiseDamage = 3, CommandType = ActionCommandType.SingleTap,
                       Applies = System.Array.Empty<StatusApplication>() };

        static SkillData Mag(Element elem = Element.Neutral, float power = 1.2f)
            => new() { Id = "sm", Type = SkillType.Magical, DamageType = DamageType.Magical,
                       Element = elem, Target = TargetMode.SingleEnemy, PowerMultiplier = power,
                       HitCount = 1, PoiseDamage = 2, CommandType = ActionCommandType.SingleTap,
                       Applies = System.Array.Empty<StatusApplication>() };

        static CombatUnit MkUnit(string id, TeamSide side, Element elem = Element.Neutral,
                                 float str = 10, float con = 10, float @int = 10,
                                 int poiseMax = 30, HeroClass cls = HeroClass.Slayer)
        {
            var u = new CombatUnit { DefId = id, DisplayNameKey = id, Side = side,
                                     Row = Row.Front, Element = elem, Class = cls, PoiseMax = poiseMax };
            u.BasePrimary = new PrimaryStats(str, con, @int, 10, 10, 10);
            return u;
        }

        static CombatSimulation Duel(ulong seed, SkillData hSkill, SkillData eSkill,
                                     Element hElem = Element.Neutral, Element eElem = Element.Neutral,
                                     float hStr = 10, float hCon = 10, float hInt = 10,
                                     float eStr = 10, float eCon = 10, int hPoise = 30,
                                     HeroClass hCls = HeroClass.Slayer)
        {
            var sim = new CombatSimulation(seed);
            var h = MkUnit("hero", TeamSide.Player, hElem, hStr, hCon, hInt, hPoise, hCls);
            h.Skills.Add(new SkillRuntime(hSkill, 0));
            var e = MkUnit("enemy", TeamSide.Enemy, eElem, eStr, eCon);
            e.Skills.Add(new SkillRuntime(eSkill, 0));
            sim.AddUnit(h);
            sim.AddUnit(e, TestFactory.SimpleAi());
            sim.Start();
            return sim;
        }

